package com.nova.security;
import com.nova.auth.User; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.Claims; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService {private final SecretKey key; private final long expiry; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms:86400000}") long expiry){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("app.jwt.secret must be at least 32 bytes");this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiry=expiry;} public String generate(User user){long now=System.currentTimeMillis();return Jwts.builder().subject(user.getEmail()).claim("role",user.getRole().name()).claim("name",user.getName()).issuedAt(new Date(now)).expiration(new Date(now+expiry)).signWith(key).compact();} public Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public boolean valid(String token,String email){try{return claims(token).getSubject().equalsIgnoreCase(email)&&claims(token).getExpiration().after(new Date());}catch(Exception e){return false;}}}
